package native

import (
	"bytes"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"testing"
)

// Independent synthetic wire fixture follows AWS's documented offsets, UUID
// half ordering, and SHA-256("hello"). It is not generated by Encode.
func fixture() []byte {
	b := make([]byte, 125)
	binary.BigEndian.PutUint32(b[:4], 116)
	copy(b[4:36], []byte("output_stream_data              "))
	binary.BigEndian.PutUint32(b[36:40], 1)
	binary.BigEndian.PutUint64(b[40:48], 1700000000000)
	copy(b[64:80], []byte{0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff, 0, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77})
	digest, _ := hex.DecodeString("2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824")
	copy(b[80:112], digest)
	binary.BigEndian.PutUint32(b[112:116], 1)
	binary.BigEndian.PutUint32(b[116:120], 5)
	copy(b[120:], "hello")
	return b
}

func TestIndependentWireFixture(t *testing.T) {
	b := fixture()
	m, err := Decode(b)
	if err != nil {
		t.Fatal(err)
	}
	if m.ID.String() != "00112233-4455-6677-8899-aabbccddeeff" || m.Type != outputStream || m.Sequence != 0 || string(m.Payload) != "hello" {
		t.Fatal("incorrect independent fixture interpretation")
	}
	encoded, err := Encode(m)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(encoded, b) {
		t.Fatal("wire bytes differ from independently specified fixture")
	}
	b[120] = 'X'
	if string(m.Payload) != "hello" {
		t.Fatal("decoder retained mutable network buffer")
	}
	for _, format := range []string{"%v", "%+v", "%#v"} {
		if bytes.Contains([]byte(fmt.Sprintf(format, m)), []byte("hello")) {
			t.Fatal("message formatting exposed payload")
		}
	}
}

func TestMalformedFrames(t *testing.T) {
	for n := 0; n < 120; n++ {
		if _, err := Decode(fixture()[:n]); err == nil {
			t.Fatalf("accepted %d-byte header", n)
		}
	}
	for _, tt := range []struct {
		name string
		edit func([]byte)
	}{
		{"header length", func(b []byte) { binary.BigEndian.PutUint32(b[:4], 0xffffffff) }},
		{"schema", func(b []byte) { binary.BigEndian.PutUint32(b[36:40], 2) }},
		{"type", func(b []byte) { b[4] = '!' }},
		{"length", func(b []byte) { binary.BigEndian.PutUint32(b[116:120], 0xffffffff) }},
		{"digest", func(b []byte) { b[80] ^= 1 }},
		{"negative sequence", func(b []byte) { binary.BigEndian.PutUint64(b[48:56], 0xffffffffffffffff) }},
		{"flags", func(b []byte) { binary.BigEndian.PutUint64(b[56:64], 4) }},
		{"missing date", func(b []byte) { clear(b[40:48]) }},
		{"missing UUID", func(b []byte) { clear(b[64:80]) }},
		{"payload type", func(b []byte) { binary.BigEndian.PutUint32(b[112:116], 100) }},
	} {
		t.Run(tt.name, func(t *testing.T) {
			b := fixture()
			tt.edit(b)
			if _, err := Decode(b); err == nil {
				t.Fatal("accepted malformed frame")
			}
		})
	}
	if _, err := Decode(append(fixture(), 0)); err == nil {
		t.Fatal("trailing payload accepted")
	}
	if _, err := Decode(make([]byte, framePrefix+MaxPayload+1)); err == nil {
		t.Fatal("unbounded frame accepted")
	}
}

func FuzzDecode(f *testing.F) {
	f.Add(fixture())
	f.Add([]byte{})
	f.Add(make([]byte, 120))
	f.Fuzz(func(t *testing.T, b []byte) {
		m, err := Decode(b)
		if err == nil {
			if len(m.Payload) > MaxPayload {
				t.Fatal("unbounded payload")
			}
			if _, err := Encode(m); err != nil && m.Type != startPublication && m.Type != pausePublication {
				t.Fatal("validated frame cannot encode")
			}
		}
	})
}
